 40	import org.junit.jupiter.api.Test;
 41	import org.springframework.beans.factory.annotation.Autowired;
 42	import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
 43	import org.springframework.boot.test.context.SpringBootTest;
 44	import org.springframework.http.MediaType;
 45	import org.springframework.test.context.DynamicPropertyRegistry;
 46	import org.springframework.test.context.DynamicPropertySource;
 47	import org.springframework.test.web.servlet.MockMvc;
 48	import org.springframework.test.web.servlet.MvcResult;
 49	
 50	import com.sun.net.httpserver.HttpServer;
 51	
 52	@SpringBootTest
 53	@AutoConfigureMockMvc
 54	class FluxoPedidoTest {
 55	
 56	    static final HttpServer TRANSLOG = subir();
 57	
 58	    static HttpServer subir() {
 59	        try {
 60	            HttpServer s = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
 61	            s.createContext("/v2/quote", ex -> {
 62	                String q = ex.getRequestURI().getQuery();
 63	                String corpo = q.contains("zip=99999999")
 64	                        ? "{\"error\":\"ZIP_NOT_SERVED\"}"
 65	                        : "{\"price_cents\":3310,\"eta_hours\":41}";
 66	                byte[] b = corpo.getBytes(StandardCharsets.UTF_8);
 67	                ex.sendResponseHeaders(200, b.length);
 68	                ex.getResponseBody().write(b);
 69	                ex.close();
 70	            });
 71	            s.start();
 72	            return s;
 73	        } catch (IOException e) {
 74	            throw new IllegalStateException(e);
 75	        }
 76	    }
 77	
 78	    @DynamicPropertySource
 79	    static void props(DynamicPropertyRegistry r) {
 80	        r.add("translog.url", () -> "http://localhost:" + TRANSLOG.getAddress().getPort());
 81	    }
 82	
 83	    @AfterAll
 84	    static void parar() {
 85	        TRANSLOG.stop(0);
 86	    }
 87	
 88	    @Autowired
 89	    MockMvc mvc;
 90	
 91	    static String compra(String cpf, String itens, String cep, String regiao, String modal, String cupom,
 92	            String forma, int parcelas, String nivel) {
 93	        return """
 94	                {"cliente":{"cpf":"%s","email":"a@b.com"},"itens":%s,"cep":"%s","regiao":"%s",
 95	                 "modalidadeEntrega":"%s",%s"formaPagamento":"%s","parcelas":%d,"nivelClube":"%s"}"""
 96	                .formatted(cpf, itens, cep, regiao, modal, cupom == null ? "" : "\"cupom\":\"" + cupom + "\",",
 97	                        forma, parcelas, nivel);
 98	    }
 99	
100	    String id(MvcResult r) throws Exception {
101	        String corpo = r.getResponse().getContentAsString();
102	        int i = corpo.indexOf("\"id\":\"") + 6;
103	        return corpo.substring(i, corpo.indexOf('"', i));
104	    }
105	
106	    @Test
107	    void resumoComTransLogPrazoRegionalEPix() throws Exception {
108	        mvc.perform(post("/checkout/resumo").contentType(MediaType.APPLICATION_JSON)
109	                .content(compra("11111111111", "[{\"sku\":\"CAM-001\",\"quantidade\":2}]", "01310100", "NORTE",
110	                        "EXPRESSA", null, "PIX", 1, "BRONZE")))
111	                .andExpect(status().isOk())
112	                .andExpect(jsonPath("$.subtotalProdutos").value(159.80))
113	                .andExpect(jsonPath("$.frete").value(33.10))
114	                .andExpect(jsonPath("$.prazoEntregaDias").value(5))
115	                .andExpect(jsonPath("$.seguro").value(4.00))
116	                .andExpect(jsonPath("$.ajustePagamento").value(-9.84));
117	    }
118	
119	    @Test
120	    void erros() throws Exception {
121	        mvc.perform(post("/checkout/resumo").contentType(MediaType.APPLICATION_JSON)
122	                .content(compra("11111111111", "[{\"sku\":\"CAM-001\",\"quantidade\":1}]", "99999999", "SUL",
123	                        "ECONOMICA", null, "PIX", 1, "BRONZE")))
124	                .andExpect(status().isUnprocessableEntity())
125	                .andExpect(jsonPath("$.erro").value("MODALIDADE_INDISPONIVEL"));
126	        mvc.perform(post("/checkout/resumo").contentType(MediaType.APPLICATION_JSON)
127	                .content(compra("11111111111", "[{\"sku\":\"REL-001\",\"quantidade\":1}]", "01310100", "SUL",
128	                        "MOTOBOY", null, "PIX", 1, "BRONZE")))
129	                .andExpect(jsonPath("$.erro").value("PRODUTO_FORA_DE_LINHA"));
130	    }
131	
132	    @Test
133	    void pagamentoIdempotenteEstoqueCreditoECancelamento() throws Exception {
134	        String cpf = "22222222222";
135	        MvcResult r = mvc.perform(post("/pedidos").contentType(MediaType.APPLICATION_JSON)
136	                .content(compra(cpf, "[{\"sku\":\"MOC-001\",\"quantidade\":1}]", "01310100", "SUDESTE",
137	                        "MOTOBOY", null, "CARTAO", 1, "PRATA")))
138	                .andExpect(status().isCreated())
139	                .andExpect(jsonPath("$.situacao").value("AGUARDANDO_PAGAMENTO"))
140	                .andExpect(jsonPath("$.resumo.creditoProximaCompra").value(3.20))
141	                .andReturn();
142	        String id = id(r);
143	        String pag = "{\"idTransacao\":\"TX-1\",\"pagoEm\":\"" + Instant.now() + "\"}";
144	        for (int i = 0; i < 2; i++) {
145	            mvc.perform(post("/pedidos/" + id + "/pagamento").contentType(MediaType.APPLICATION_JSON).content(pag))
146	                    .andExpect(status().isOk()).andExpect(jsonPath("$.situacao").value("PAGO"));
147	        }
148	        mvc.perform(get("/produtos/MOC-001")).andExpect(jsonPath("$.estoque").value(0));
149	        mvc.perform(get("/clientes/" + cpf)).andExpect(jsonPath("$.saldoCredito").value(3.20));
150	        mvc.perform(get("/clientes/" + cpf + "/avisos")).andExpect(jsonPath("$.length()").value(1));
151	
152	        mvc.perform(post("/pedidos/" + id + "/cancelamento")).andExpect(status().isOk());
153	        mvc.perform(get("/produtos/MOC-001")).andExpect(jsonPath("$.estoque").value(1));
154	        mvc.perform(get("/clientes/" + cpf)).andExpect(jsonPath("$.saldoCredito").value(0.00));
155	        mvc.perform(get("/clientes/" + cpf + "/avisos")).andExpect(jsonPath("$.length()").value(2));
156	        mvc.perform(post("/pedidos/" + id + "/envio").contentType(MediaType.APPLICATION_JSON)
157	                .content("{\"codigoRastreio\":\"X\"}")).andExpect(status().isConflict());
158	    }
159	
160	    @Test
161	    void pagamentoAposQuarentaEOitoHorasCancela() throws Exception {
162	        MvcResult r = mvc.perform(post("/pedidos").contentType(MediaType.APPLICATION_JSON)
163	                .content(compra("33333333333", "[{\"sku\":\"MEI-001\",\"quantidade\":1}]", "01310100", "SUL",
164	                        "RETIRADA_LOJA", null, "PIX", 1, "BRONZE")))
165	                .andReturn();
166	        String id = id(r);
167	        String tarde = "{\"idTransacao\":\"TX-9\",\"pagoEm\":\"" + Instant.now().plusSeconds(49 * 3600) + "\"}";
168	        mvc.perform(post("/pedidos/" + id + "/pagamento").contentType(MediaType.APPLICATION_JSON).content(tarde))
169	                .andExpect(status().isConflict()).andExpect(jsonPath("$.erro").value("PEDIDO_EXPIRADO"));
170	        mvc.perform(get("/pedidos/" + id)).andExpect(jsonPath("$.situacao").value("CANCELADO"));
171	    }
172	}

